static int scrub_setup_wr_ctx ( struct scrub_wr_ctx * wr_ctx , struct btrfs_device * dev , int is_dev_replace ) { WARN_ON ( wr_ctx -> wr_curr_bio != NULL ) ; mutex_init ( & wr_ctx -> wr_lock ) ; wr_ctx -> wr_curr_bio = NULL ; WARN_ON ( ! dev -> bdev ) ; wr_ctx -> pages_per_wr_bio = SCRUB_PAGES_PER_WR_BIO ; wr_ctx -> tgtdev = dev ; atomic_set ( & wr_ctx -> flush_all_writes , 0 ) ; return 0 ; } 